w['revenue'])) ?></strong></div><?php endforeach; ?></div></section><section class="admin-panel"><div class="panel-heading"><div><p class="eyebrow">Orders</p><h2>By status</h2></div></div><div class="demo-list"><?php foreach($demo['statuses'] as $row): ?><div><span><?= e($row['label']) ?></span><strong><?= number_format($row['total']) ?></strong></div><?php endforeach; ?></div></section></div><section class="admin-panel"><div class="panel-heading"><div><p class="eyebrow">Products</p><h2>Top performers</h2></div><span><?= number_format($demo['product_count']) ?> catalogue products</span></div><div class="demo-products"><div class="demo-product-head"><span>Product</span><span>Units sold</span><span>Revenue</span></div><?php foreach($demo['products'] as $product): ?><div><span><?= e($product['name']) ?></span><strong><?= number_format($product['units']) ?></strong><strong><?= e($money($product['revenue'])) ?></strong></div><?php endforeach; ?></div></section></section></main><style>.demo-wrap{display:grid;gap:20px}.demo-notice{display:flex;align-items:center;gap:10px;border:1px solid #d9d9d0;border-radius:12px;background:#f2ede0;padding:13px 16px;color:#6b5b3d;font-size:12px}.demo-notice svg{width:16px}.demo-grid{display:grid;grid-template-columns:1.25fr .75fr;gap:20px}.demo-period{font-size:11px;color:#85877d}.demo-bars,.demo-list{display:grid;gap:14px}.demo-bar-row{display:grid;grid-template-columns:38px 1fr 90px;align-items:center;gap:12px;font-size:11px}.demo-bar-row>div{height:10px;overflow:hidden;border-radius:999px;background:#eef0e8}.demo-bar-row i{display:block;height:100%;border-radius:inherit;background:#687158}.demo-bar-row strong{text-align:right;font-size:11px;font-weight:600}.demo-list div{display:flex;justify-content:space-between;border-top:1px solid #e2e2da;padding-top:13px;font-size:12px}.demo-list div:first-child{border-top:0;padding-top:0}.demo-list span,.demo-products span{color:#77796f}.demo-list strong{color:#687158}.demo-products{display:grid;gap:0}.demo-product-head,.demo-products>div:not(.demo-product-head){display:grid;grid-template-columns:1fr 110px 120px;gap:20px;align-items:center;padding:15px 0;border-top:1px solid #e2e2da;font-size:12px}.demo-product-head{border-top:0;padding-top:0;color:#92948a;font-size:10px;text-transform:uppercase;letter-spacing:.12em}.demo-products strong{text-align:right;color:#252820;font-weight:600}@media(max-width:800px){.demo-grid{grid-template-columns:1fr}.demo-product-head,.demo-products>div:not(.demo-product-head){grid-template-columns:1fr 75px 95px;gap:10px}.demo-bar-row{grid-template-columns:32px 1fr 78px}}
